    private string? maTruongBo;
    private string? selectedNamHoc;
    private string? selectedCapHoc;
    private string  tenTruong = "Trường học";

    private string _tab = "giangday";

    // ── Phân công giảng dạy ──
    private List<PhanCongGiangDayDTO>? AllGiangDay;
    private List<PhanCongGiangDayDTO>? FilteredGiangDay;
    private List<string> _gdMonList   = new();
    private string _gdFilterMon   = "";
    private string _gdFilterHocKy = "";
    private string _gdSearch      = "";
    private int    _gdPage        = 1;
    private int    _gdPageSize    = 20;

    // ── Phân công chủ nhiệm ──
    private List<PhanCongChuNhiemDTO>? AllChuNhiem;
    private List<PhanCongChuNhiemDTO>? FilteredChuNhiem;
    private string _cnFilterHocKy = "";
    private string _cnSearch      = "";
    private int    _cnPage        = 1;
    private int    _cnPageSize    = 20;

    // ── Học kỳ ──
    private List<HocKyDTO> HocKyList        = new();
    private HocKyDTO?      _currentHocKy    = null;   // HK đang diễn ra (tự động active)

    // ── Loading ──
    private bool _isLoading = false;

    // ── Toast ──
    private string _toastMsg  = "";
    private string _toastCss  = "";
