    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong      = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadData();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await JS.InvokeVoidAsync("eval", @"
                if (!window._fileDownloadRegistered) {
                    window.downloadFileFromBase64 = function(filename, base64) {
                        const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
                        const blob  = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
                        const url   = URL.createObjectURL(blob);
                        const a     = document.createElement('a');
                        a.href = url; a.download = filename;
                        document.body.appendChild(a); a.click();
                        document.body.removeChild(a); URL.revokeObjectURL(url);
                    };
                    window._fileDownloadRegistered = true;
                }
            ");
        }
    }

    // ── LOAD DATA ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        _isLoading = true;
        StateHasChanged();

        try
        {
            var capHoc = selectedCapHoc ?? "1";

            // ── Load song song 4 nguồn từ LoginID_Index ──
            var monHocTask = DaoTaoService.hGetMonHoc(maTruongBo);
            var lopTask    = TruongService.hGetDanhSachLop(maTruongBo, capHoc, selectedNamHoc);
            var khoiTask   = TruongService.hGetDanhSachKhoi(maTruongBo, capHoc);
            var hocKyTask  = TruongService.hGetDanhSachHocKy(selectedNamHoc);

            await Task.WhenAll(monHocTask, lopTask, khoiTask, hocKyTask);

            // Build dict: idmonhocso (dạng "01"…) → ten_mon_hoc
            var monHocDict = monHocTask.Result
                .Where(m => !string.IsNullOrEmpty(m.idmonhocso))
                .ToDictionary(
                    m => m.idmonhocso!.PadLeft(2, '0'),
                    m => m.ten_mon_hoc ?? m.idmonhocso!,
                    StringComparer.OrdinalIgnoreCase);

            // Build dict: IdLopBo → (TenLop, MaKhoiBo)
            var lopDict = lopTask.Result
                .Where(l => l.IdLopBo > 0)
                .ToDictionary(
                    l => l.IdLopBo,
                    l => (TenLop: l.TenLop ?? "", MaKhoiBo: l.MaKhoiBo?.PadLeft(2, '0') ?? ""));

            // Build set mã khối hợp lệ theo cấp học (để filter phân công)
            var maKhoiSet = khoiTask.Result
                .Where(k => !string.IsNullOrEmpty(k.MaKhoiBo))
                .Select(k => k.MaKhoiBo!.PadLeft(2, '0'))
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            // Lưu danh sách học kỳ + tự động active HK hiện tại
            HocKyList = hocKyTask.Result;
            var now = DateTime.Now;
            _currentHocKy = HocKyList.FirstOrDefault(hk =>
                hk.ThoiGianBatDau.HasValue && hk.ThoiGianKetThuc.HasValue &&
                now >= hk.ThoiGianBatDau.Value && now <= hk.ThoiGianKetThuc.Value);

            // Nếu có học kỳ hiện tại → auto-select khi mới load
            if (_currentHocKy != null)
            {
                if (string.IsNullOrEmpty(_gdFilterHocKy))
                    _gdFilterHocKy = _currentHocKy.MaHocKy.ToString();
                if (string.IsNullOrEmpty(_cnFilterHocKy))
                    _cnFilterHocKy = _currentHocKy.MaHocKy.ToString();
            }

            // ── Load song song 2 bảng phân công từ LoginID_School_Dev ──
            var gdTask = TruongService.hGetDanhSachPhanCongGiangDay(
                maTruongBo, selectedNamHoc,
                monHocDict, lopDict, maKhoiSet);

            var cnTask = TruongService.hGetDanhSachPhanCongChuNhiem(
                maTruongBo, selectedNamHoc,
                lopDict, maKhoiSet);

            await Task.WhenAll(gdTask, cnTask);

            AllGiangDay = gdTask.Result;
            AllChuNhiem = cnTask.Result;

            // Build danh sách môn học duy nhất để filter dropdown
            _gdMonList = AllGiangDay
                .Select(g => g.TenMonHoc)
                .Where(t => !string.IsNullOrEmpty(t))
                .Distinct()
                .OrderBy(x => x)
                .ToList()!;

            ApplyGiangDayFilter();
            ApplyChuNhiemFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadData error: {ex.Message}");
            await ShowToast("Lỗi tải dữ liệu phân công!", "toast-error", "error");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER GIẢNG DẠY ──
    private void ApplyGiangDayFilter()
    {
        if (AllGiangDay == null) { FilteredGiangDay = new(); return; }

        var q = AllGiangDay.AsEnumerable();

        // Filter học kỳ: so sánh MaHocKy (string) với giá trị dropdown
        if (!string.IsNullOrEmpty(_gdFilterHocKy))
            q = q.Where(g => g.MaHocKy == _gdFilterHocKy);

        if (!string.IsNullOrEmpty(_gdFilterMon))
            q = q.Where(g => g.TenMonHoc == _gdFilterMon);

        if (!string.IsNullOrWhiteSpace(_gdSearch))
        {
            var t = _gdSearch.Trim();
            q = q.Where(g =>
                (g.HoTenGiaoVien?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (g.TenLop?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (g.TenMonHoc?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (g.MaGiaoVien?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        FilteredGiangDay = q.ToList();
        _gdPage = 1;
        StateHasChanged();
    }

    // ── FILTER CHỦ NHIỆM ──
    private void ApplyChuNhiemFilter()
    {
        if (AllChuNhiem == null) { FilteredChuNhiem = new(); return; }

        var q = AllChuNhiem.AsEnumerable();

        // Filter học kỳ: so sánh HocKy (string số kỳ) với MaHocKy dropdown
        if (!string.IsNullOrEmpty(_cnFilterHocKy))
        {
            // PhanCongChuNhiemDTO.HocKy là số kỳ ("1"/"2"), MaHocKy là mã nguyên
            // Lấy HocKyDTO tương ứng để map MaHocKy → HocKy (số kỳ)
            var selectedHK = HocKyList.FirstOrDefault(hk => hk.MaHocKy.ToString() == _cnFilterHocKy);
            if (selectedHK != null)
                q = q.Where(c => c.MaHocKy == _cnFilterHocKy ||
                                 c.HocKy   == selectedHK.HocKy.ToString());
            else
                q = q.Where(c => c.MaHocKy == _cnFilterHocKy);
        }

        if (!string.IsNullOrWhiteSpace(_cnSearch))
        {
            var t = _cnSearch.Trim();
            q = q.Where(c =>
                (c.HoTenGiaoVien?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (c.TenLop?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (c.MaGiaoVien?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        FilteredChuNhiem = q.ToList();
        _cnPage = 1;
        StateHasChanged();
    }

    // ── EXPORT GIẢNG DẠY ──
    private async Task ExportGiangDay()
    {
        if (!(FilteredGiangDay?.Any() ?? false)) return;
        try
        {
            using var wb = new ClosedXML.Excel.XLWorkbook();
            var ws = wb.Worksheets.Add("Phân công giảng dạy");

            ws.Cell(1, 1).Value = $"PHÂN CÔNG GIẢNG DẠY — NĂM HỌC {selectedNamHoc} — {tenTruong}";
            ws.Range(1, 1, 1, 7).Merge().Style
                .Font.SetBold(true).Font.SetFontSize(13)
                .Alignment.SetHorizontal(ClosedXML.Excel.XLAlignmentHorizontalValues.Center)
                .Fill.SetBackgroundColor(ClosedXML.Excel.XLColor.FromHtml("#6366f1"))
                .Font.SetFontColor(ClosedXML.Excel.XLColor.White);

            var headers = new[] { "STT", "Lớp", "Khối", "Giáo viên", "Mã GV", "Môn học", "Mã môn", "Học kỳ" };
            for (int c = 0; c < headers.Length; c++)
            {
                var cell = ws.Cell(2, c + 1);
                cell.Value = headers[c];
                cell.Style.Font.SetBold(true)
                    .Fill.SetBackgroundColor(ClosedXML.Excel.XLColor.FromHtml("#e0e7ff"))
                    .Alignment.SetHorizontal(ClosedXML.Excel.XLAlignmentHorizontalValues.Center)
                    .Border.SetOutsideBorder(ClosedXML.Excel.XLBorderStyleValues.Thin);
            }

            var list = FilteredGiangDay!.OrderBy(g => g.TenLop).ThenBy(g => g.TenMonHoc).ToList();
            for (int i = 0; i < list.Count; i++)
            {
                var g = list[i];
                int row = i + 3;
                ws.Cell(row, 1).Value = i + 1;
                ws.Cell(row, 2).Value = g.TenLop;
                ws.Cell(row, 3).Value = g.MaKhoiBo;
                ws.Cell(row, 4).Value = g.HoTenGiaoVien;
                ws.Cell(row, 5).Value = g.MaGiaoVien;
                ws.Cell(row, 6).Value = g.TenMonHoc;
                ws.Cell(row, 7).Value = g.MaMonHoc;
                ws.Cell(row, 8).Value = g.MaHocKy;
                ws.Range(row, 1, row, 8).Style.Border.SetOutsideBorder(ClosedXML.Excel.XLBorderStyleValues.Hair);
            }

            int[] widths = { 5, 10, 8, 28, 14, 26, 10, 12 };
            for (int c = 0; c < widths.Length; c++) ws.Column(c + 1).Width = widths[c];

            using var ms = new System.IO.MemoryStream();
            wb.SaveAs(ms);
            var b64  = Convert.ToBase64String(ms.ToArray());
            var name = $"PhanCongGiangDay_{selectedNamHoc}_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
            await JS.InvokeVoidAsync("downloadFileFromBase64", name, b64);
            await ShowToast("Xuất Excel thành công!", "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExportGiangDay error: {ex.Message}");
            await ShowToast("Xuất Excel thất bại!", "toast-error", "error");
        }
    }

    // ── EXPORT CHỦ NHIỆM ──
    private async Task ExportChuNhiem()
    {
        if (!(FilteredChuNhiem?.Any() ?? false)) return;
        try
        {
            using var wb = new ClosedXML.Excel.XLWorkbook();
            var ws = wb.Worksheets.Add("Phân công chủ nhiệm");

            ws.Cell(1, 1).Value = $"PHÂN CÔNG CHỦ NHIỆM — NĂM HỌC {selectedNamHoc} — {tenTruong}";
            ws.Range(1, 1, 1, 8).Merge().Style
                .Font.SetBold(true).Font.SetFontSize(13)
                .Alignment.SetHorizontal(ClosedXML.Excel.XLAlignmentHorizontalValues.Center)
                .Fill.SetBackgroundColor(ClosedXML.Excel.XLColor.FromHtml("#f59e0b"))
                .Font.SetFontColor(ClosedXML.Excel.XLColor.White);

            var headers = new[] { "STT", "Lớp", "Khối", "Giáo viên chủ nhiệm", "Mã GV", "Từ ngày", "Đến ngày", "Học kỳ" };
            for (int c = 0; c < headers.Length; c++)
            {
                var cell = ws.Cell(2, c + 1);
                cell.Value = headers[c];
                cell.Style.Font.SetBold(true)
                    .Fill.SetBackgroundColor(ClosedXML.Excel.XLColor.FromHtml("#fef3c7"))
                    .Alignment.SetHorizontal(ClosedXML.Excel.XLAlignmentHorizontalValues.Center)
                    .Border.SetOutsideBorder(ClosedXML.Excel.XLBorderStyleValues.Thin);
            }

            var list = FilteredChuNhiem!.OrderBy(c => c.TenLop).ToList();
            for (int i = 0; i < list.Count; i++)
            {
                var c   = list[i];
                int row = i + 3;
                ws.Cell(row, 1).Value = i + 1;
                ws.Cell(row, 2).Value = c.TenLop;
                ws.Cell(row, 3).Value = c.MaKhoiBo;
                ws.Cell(row, 4).Value = c.HoTenGiaoVien;
                ws.Cell(row, 5).Value = c.MaGiaoVien;
                ws.Cell(row, 6).Value = c.TuNgay?.ToString("dd/MM/yyyy") ?? "";
                ws.Cell(row, 7).Value = c.DenNgay?.ToString("dd/MM/yyyy") ?? "";
                ws.Cell(row, 8).Value = c.HocKy;
                ws.Range(row, 1, row, 8).Style.Border.SetOutsideBorder(ClosedXML.Excel.XLBorderStyleValues.Hair);
            }

            int[] widths = { 5, 10, 8, 30, 14, 14, 14, 10 };
            for (int c = 0; c < widths.Length; c++) ws.Column(c + 1).Width = widths[c];

            using var ms = new System.IO.MemoryStream();
            wb.SaveAs(ms);
            var b64  = Convert.ToBase64String(ms.ToArray());
            var name = $"PhanCongChuNhiem_{selectedNamHoc}_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
            await JS.InvokeVoidAsync("downloadFileFromBase64", name, b64);
            await ShowToast("Xuất Excel thành công!", "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExportChuNhiem error: {ex.Message}");
            await ShowToast("Xuất Excel thất bại!", "toast-error", "error");
        }
    }

    // ── TOAST ──
    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastMsg = ""; StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

